"""Build paired OG/X review pages with visible, settled-runtime layout results.

Run from the repository root after tools/trmnl/preview.ts --recap, then serve
.previews over localhost. This is a preview harness, not product markup.
"""
from pathlib import Path
import json
states=sorted(p.name.removesuffix('--payload.json') for p in Path('.previews').glob('*--payload.json'))
layouts={'markup':(800,480,1872,1404),'markup_half_horizontal':(800,240,1872,702),'markup_half_vertical':(400,480,936,1404),'markup_quadrant':(400,240,936,702)}
script='''<script>
function fitMetrics(frame,e){
  const w=frame.contentWindow;const items=[...e.children].filter(x=>x.classList.contains('block'));const visible=items.filter(x=>w.getComputedStyle(x).display!=='none');const next=items.find(x=>x.classList.contains('hidden'));const last=visible.at(-1)?.getBoundingClientRect();const bottom=Number(e.dataset.storyBottom);let nextHeight=null;
  if(next){next.classList.remove('hidden');nextHeight=next.getBoundingClientRect().height;next.classList.add('hidden');}
  return {availableHeight:bottom-e.getBoundingClientRect().top,visibleCount:visible.length,candidateCount:items.length,remainingHeight:last?bottom-last.bottom:null,nextItemHeight:nextHeight,nextItemWouldFit:nextHeight!==null&&last!==undefined&&last.bottom+nextHeight<=bottom-2,fitComplete:e.dataset.storyFit==='complete',visibleStories:visible.map(x=>x.textContent.trim().slice(0,160))};
}
function inspect(frame){const d=frame.contentDocument;const footer=d.querySelector('.title_bar');const view=d.querySelector('.view');if(!footer||!view)return {error:'Missing view or footer'};const bound=Math.min(footer.getBoundingClientRect().top,view.getBoundingClientRect().bottom);const failures=[...d.querySelectorAll('.layout span,.layout img')].filter(e=>e.getBoundingClientRect().height&&getComputedStyle(e).visibility!=='hidden'&&e.getBoundingClientRect().bottom>bound+2).map(e=>({text:(e.innerText||e.getAttribute('src')||'').slice(0,100),bottom:e.getBoundingClientRect().bottom,bound}));const images=[...d.querySelectorAll('.layout img')].filter(e=>e.getBoundingClientRect().height&&e.complete&&e.naturalWidth===0).map(e=>e.src);const tracks=[...d.querySelectorAll(".progress-bar .track")];const weapon=[...d.querySelectorAll(".layout span")].find(e=>e.textContent==="Weapon"&&e.getBoundingClientRect().height);const art=[...d.querySelectorAll(".layout img")].find(e=>e.getBoundingClientRect().height&&e.naturalWidth>200);const barsBottom=tracks.length?Math.max(...tracks.map(e=>e.getBoundingClientRect().bottom)):null;const heroHeading=[...d.querySelectorAll(".layout > .grid:first-of-type > div:first-child > span.title")].find(e=>e.getBoundingClientRect().height);let headerTextOverflow=false;if(heroHeading){const range=d.createRange();range.selectNodeContents(heroHeading);headerTextOverflow=range.getBoundingClientRect().right>heroHeading.parentElement.getBoundingClientRect().right+2;}const codes=[...d.querySelectorAll(".layout img")].filter(e=>e.src.includes("/art/qr/")&&e.getBoundingClientRect().height);return {qr:codes.map(e=>{const r=e.getBoundingClientRect();const v=view.getBoundingClientRect();return {loaded:e.complete&&e.naturalWidth>0,width:r.width,height:r.height,naturalWidth:e.naturalWidth,insideView:r.left>=v.left&&r.right<=v.right&&r.bottom<=bound+2,caption:e.parentElement.textContent.trim()};}),failures,images,headerTextOverflow,rankTextOverflow:[...d.querySelectorAll(".layout .value[data-fit-value]")].some(e=>{if(!e.getBoundingClientRect().height)return false;const range=d.createRange();range.selectNodeContents(e);return range.getBoundingClientRect().right>e.parentElement.getBoundingClientRect().right+2;}),footerTop:bound,recapRibbon:[...d.querySelectorAll("[data-recap-ribbon] span")].filter(e=>e.getBoundingClientRect().height).map(e=>{const range=d.createRange();range.selectNodeContents(e);const r=range.getBoundingClientRect();const p=e.parentElement.getBoundingClientRect();return {fontSize:parseFloat(frame.contentWindow.getComputedStyle(e).fontSize),textWidth:r.width,width:p.width,height:r.height,singleLine:range.getClientRects().length===1,horizontalOverflow:r.right>p.right+1};}),fit:[...d.querySelectorAll("[data-story-list]")].map(e=>fitMetrics(frame,e)),listMetrics:[...d.querySelectorAll("[data-story-list]")].map(e=>({box:{top:e.getBoundingClientRect().top,bottom:e.getBoundingClientRect().bottom,height:e.getBoundingClientRect().height},parent:{top:e.parentElement.getBoundingClientRect().top,bottom:e.parentElement.getBoundingClientRect().bottom,height:e.parentElement.getBoundingClientRect().height},maxHeight:e.style.maxHeight,items:[...e.querySelectorAll(":scope > .block")].map(x=>({text:x.textContent.trim().slice(0,60),display:frame.contentWindow.getComputedStyle(x).display,hidden:x.classList.contains("hidden"),top:x.getBoundingClientRect().top,bottom:x.getBoundingClientRect().bottom}))})),storyGaps:[...d.querySelectorAll(".layout .grid.grid--cols-1")].filter(e=>e.getBoundingClientRect().height&&e.querySelector(":scope > .flex.flex--row .grow[data-clamp]")&&e.querySelector(":scope > .flex.flex--row .no-shrink.label")).map(e=>{const story=e.querySelector(":scope > .flex.flex--row .grow[data-clamp]");const stats=e.querySelector(":scope > .flex.flex--row .no-shrink.label");return {story:story.textContent.trim().slice(0,70),gap:stats.getBoundingClientRect().top-story.getBoundingClientRect().bottom,computedGap:frame.contentWindow.getComputedStyle(e).gap};}),headerGrids:[...d.querySelectorAll(".layout > .grid:first-of-type .grid")].map(e=>({classes:e.className,gap:frame.contentWindow.getComputedStyle(e).gap})),barToGearGap:weapon&&barsBottom!==null?weapon.getBoundingClientRect().top-barsBottom:null,sceneTop:art?art.getBoundingClientRect().top:null};}
for(const frame of document.querySelectorAll('iframe'))frame.addEventListener('load',async()=>{await frame.contentDocument.fonts.ready;while(frame.contentWindow.TRMNL_PLUGINS_READY!==true)await new Promise(resolve=>requestAnimationFrame(resolve));requestAnimationFrame(()=>requestAnimationFrame(()=>{const result=inspect(frame);document.querySelector(`[data-result="${frame.name}"]`).textContent=JSON.stringify(result);if([...document.querySelectorAll('pre[data-result]')].every(e=>e.textContent!=='Checking…'))document.querySelector('button').hidden=false;}));});
</script>'''
for state in states:
 for layout,(ow,oh,xw,xh) in layouts.items():
  cells=[]
  for device,w,h,scale in [('og',ow,oh,1),('x',xw,xh,0.45 if xh>1000 or xw>1000 else 0.7)]:
   name=f'{state}--{device}--{layout}'
   revision=Path(f'.previews/{name}.html').stat().st_mtime_ns
   cells.append(f'<section><h2>{device.upper()} · {state} · {layout}</h2><div class="stage" style="width:{w*scale}px;height:{h*scale}px"><iframe title="{name}" name="{name}" src="{name}.html?review={revision}" style="width:{w}px;height:{h}px;transform:scale({scale});transform-origin:top left"></iframe></div><pre data-result="{name}">Checking…</pre></section>')
  html='<html><head><meta charset="utf-8"><title>Recap layout review</title><style>body{margin:16px;font:16px system-ui;background:#dedede}main{display:flex;gap:24px;align-items:flex-start}h2{font-size:16px}iframe{border:0;display:block}pre{max-width:820px;white-space:pre-wrap;font-size:12px}.stage{overflow:hidden}</style></head><body><button hidden>Results ready</button><main>'+''.join(cells)+'</main>'+script+'</body></html>'
  Path(f'.previews/review--{state}--{layout}.html').write_text(html)
Path('.previews/recap-review-index.html').write_text('<h1>Recap previews</h1>'+''.join(f'<p><a href="review--{s}--{l}.html">{s} · {l}</a></p>' for s in states for l in layouts))
print(f'Created {len(states)*len(layouts)} review pages for {len(states)} states.')
